/* ---------- drawing helpers for this lesson (prefixed T3_ so they never clash with engine globals) ---------- */
const T3_F='font-family="Nunito Sans, sans-serif"';
const T3_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${T3_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}"${o.ex?' '+o.ex:''}>${t}</text>`;
const T3_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const T3_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw??2}"${o.ex?' '+o.ex:''}/>`;
const T3_arrow=(x1,y1,x2,y2,col='#18213A',w=3,h=16)=>{const a=Math.atan2(y2-y1,x2-x1);return T3_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const T3_sb=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const T3_sp=(a,b)=>`${a}<tspan baseline-shift="super" font-size="70%">${b}</tspan>`;
const T3_GREY='#5C6577', T3_STEEL='#495057', T3_AL='#DEE2E6', T3_HOT='#FFE8CC', T3_COOL='#DBE4FF', T3_FRESH='#D3F9D8', T3_BURNT='#ADB5BD';
/* a wheel (turbine or compressor) with n curved blades */
const T3_wheel=(x,y,r,col,n=8,fill='#FFFFFF')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${col}" stroke-width="4"/>`+Array.from({length:n},(_,i)=>{const a=i*2*Math.PI/n,b=a+.55;return `<path d="M${(x+r*.22*Math.cos(a)).toFixed(1)},${(y+r*.22*Math.sin(a)).toFixed(1)} Q${(x+r*.62*Math.cos(a+.15)).toFixed(1)},${(y+r*.62*Math.sin(a+.15)).toFixed(1)} ${(x+r*.88*Math.cos(b)).toFixed(1)},${(y+r*.88*Math.sin(b)).toFixed(1)}" fill="none" stroke="${col}" stroke-width="3"/>`}).join('')+`<circle cx="${x}" cy="${y}" r="${r*.18}" fill="${col}"/>`;
/* a ring of n vanes around a turbine: open=0 closed (tangential), 1 open (pointing in) */
const T3_vanes=(x,y,R,open,col,n=10)=>`<circle cx="${x}" cy="${y}" r="${R}" fill="none" stroke="#B9C0D4" stroke-width="2" stroke-dasharray="6 5"/>`+Array.from({length:n},(_,i)=>{const a=i*2*Math.PI/n,cx=x+R*.72*Math.cos(a),cy=y+R*.72*Math.sin(a),t=a+Math.PI/2-open*1.05,l=R*.2;return T3_L((cx-l*Math.cos(t)).toFixed(1),(cy-l*Math.sin(t)).toFixed(1),(cx+l*Math.cos(t)).toFixed(1),(cy+l*Math.sin(t)).toFixed(1),col,6)}).join('')+`<circle cx="${x}" cy="${y}" r="${R*.38}" fill="#E6E9FB" stroke="${BLU}" stroke-width="3"/>`;
/* a cylinder in section, ports on its walls; piston top at py */
const T3_cyl=(x,y0,w,y1,py,o={})=>`${o.gas?`<rect x="${x}" y="${y0}" width="${w}" height="${py-y0}" fill="${o.gas}"/>`:''}${T3_L(x,y0,x,y1,'#343A40',5)}${T3_L(x+w,y0,x+w,y1,'#343A40',5)}${T3_L(x-10,y0,x+w+10,y0,'#343A40',7)}<rect x="${x+4}" y="${py}" width="${w-8}" height="${o.ph||46}" rx="5" fill="${T3_AL}" stroke="${T3_STEEL}" stroke-width="3"/>`;
/* a pressure gauge: needle at fraction f of the 240-degree dial */
const T3_gauge=(x,y,r,f,lab,col)=>{const a=(-210+240*f)*Math.PI/180;return `<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="${T3_STEEL}" stroke-width="4"/>`+[0,.25,.5,.75,1].map(q=>{const b=(-210+240*q)*Math.PI/180;return T3_L((x+r*.78*Math.cos(b)).toFixed(1),(y+r*.78*Math.sin(b)).toFixed(1),(x+r*.92*Math.cos(b)).toFixed(1),(y+r*.92*Math.sin(b)).toFixed(1),T3_GREY,3)}).join('')+T3_L(x,y,(x+r*.72*Math.cos(a)).toFixed(1),(y+r*.72*Math.sin(a)).toFixed(1),col,5)+`<circle cx="${x}" cy="${y}" r="7" fill="${col}"/>`+T3_T(x,y+r+30,lab,{fs:24,fw:800,a:'middle',fill:col})};
/* a stopwatch */
const T3_watch=(x,y,r,col,txt)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/><rect x="${x-8}" y="${y-r-14}" width="16" height="12" rx="3" fill="${col}"/>`+T3_L(x,y,x+r*.5,y-r*.5,col,4)+(txt?T3_T(x,y+r+30,txt,{fs:24,fw:800,a:'middle',fill:col}):'');
/* a horizontal bar with a label inside */
const T3_bar=(x,y,w,h,fill,st,lab,lc)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="6" fill="${fill}" stroke="${st}" stroke-width="2.5"/>`+(lab?T3_T(x+w/2,y+h/2+8,lab,{fs:22,fw:800,a:'middle',fill:lc||'#18213A'}):'');

