 s+=g('pop',tw,`<path d="M120,196 H40 V44 H240" fill="none" stroke="${MAG}" stroke-width="5" stroke-dasharray="12 8"/>`+`<circle cx="40" cy="120" r="16" fill="#FFFFFF" stroke="${MAG}" stroke-width="4"/>`+T3_L(29,131,51,109,MAG,4)+T3_T(60,32,'wastegate bypass',{fs:22,fw:800,fill:MAG}));
